CREATE TABLE `deg_wallets_provider_links` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `deg_wallet_id` int unsigned DEFAULT NULL,
  `provider_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `deg_wallets_provider_links_unique` (`deg_wallet_id`,`provider_id`),
  KEY `deg_wallets_provider_links_fk` (`deg_wallet_id`),
  KEY `deg_wallets_provider_links_inv_fk` (`provider_id`),
  CONSTRAINT `deg_wallets_provider_links_fk` FOREIGN KEY (`deg_wallet_id`) REFERENCES `deg_wallets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `deg_wallets_provider_links_inv_fk` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
