DROP TABLE IF EXISTS `order_baps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_baps` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `order_id` varchar(255) DEFAULT NULL,
  `bpp_id` varchar(255) DEFAULT NULL,
  `bpp_uri` varchar(255) DEFAULT NULL,
  `currency` varchar(255) DEFAULT NULL,
  `delivery_status` varchar(255) DEFAULT NULL,
  `descriptor` json DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `billing` json DEFAULT NULL,
  `fulfillments` json DEFAULT NULL,
  `created_date` datetime(6) DEFAULT NULL,
  `last_updated_date` datetime(6) DEFAULT NULL,
  `quote` json DEFAULT NULL,
  `transaction_id` varchar(255) DEFAULT NULL,
  `message_id` varchar(255) DEFAULT NULL,
  `payments` json DEFAULT NULL,
  `items` json DEFAULT NULL,
  `domain` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `published_at` datetime(6) DEFAULT NULL,
  `created_by_id` int unsigned DEFAULT NULL,
  `updated_by_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_baps_created_by_id_fk` (`created_by_id`),
  KEY `order_baps_updated_by_id_fk` (`updated_by_id`),
  CONSTRAINT `order_baps_created_by_id_fk` FOREIGN KEY (`created_by_id`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_baps_updated_by_id_fk` FOREIGN KEY (`updated_by_id`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1015 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
